<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Validation\ValidationException;

class Laporan extends Model
{
    use HasFactory;

    /**
     * Monthly reports are generated by the scheduler, not edited by users.
     * This includes old reports whose PDF path still uses the public disk.
     */
    public function isSystemGenerated(): bool
    {
        return strtolower(trim((string) $this->jenis)) === 'laporan bulanan'
            || str_starts_with((string) $this->berkas, 'bwi/reports/');
    }

    protected static function booted(): void
    {
        static::saving(function (self $report): void {
            $previousType = strtolower(trim((string) $report->getRawOriginal('jenis')));
            $previousFile = (string) $report->getRawOriginal('berkas');

            if ($report->isSystemGenerated()
                || $previousType === 'laporan bulanan'
                || str_starts_with($previousFile, 'bwi/reports/')) {
                throw ValidationException::withMessages([
                    'berkas' => 'Laporan bulanan otomatis adalah arsip dan tidak dapat dibuat atau diubah secara manual.',
                ]);
            }
        });

        static::deleting(function (self $report): void {
            if ($report->isSystemGenerated()) {
                throw ValidationException::withMessages([
                    'berkas' => 'Arsip laporan bulanan otomatis tidak dapat dihapus.',
                ]);
            }
        });
    }

    public function cabangs(): BelongsTo
    {
        return $this->belongsTo(Cabang::class, 'cabang_id', 'id');
    }
}
